'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let variant=document.body.dataset.variant,step=0,selected=null,notes=true;
const state={A:{rate:20,connected:false,paid:false,refund:false,sent:false},B:{joined:false,applied:false},C:{joined:false,sent:false}};
try{selected=JSON.parse(localStorage.getItem('n3-cjm-selection-v1')||'null')}catch{}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const button=(label,action='next',kind='primary')=>`<button class="${kind}" data-action="${action}">${label} <span aria-hidden="true">→</span></button>`;
const notice=t=>`<div class="notice">${t}</div>`;
const row=(a,b)=>`<div class="row"><span>${a}</span><strong>${b}</strong></div>`;
const panel=(title,body,cl='')=>`<section class="panel ${cl}"><h3>${title}</h3>${body}</section>`;
const linkbox=()=>`<label class="tiny muted" for="share-link">${variant==='A'?'Ссылка вступления в программу':'Ваша демонстрационная ссылка'}</label><div class="linkbox"><input id="share-link" readonly value="${variant==='A'?'https://proofwall.example/partners/join':'https://proofwall.example/r/'+(variant==='B'?'anna':'studio')}"><button class="secondary" data-action="copy">Копировать</button></div>`;
function graph(){return `<div class="chart" aria-label="Иллюстративный рост рекомендаций">${[24,32,29,43,38,56,61,54,78,86,95,100].map(h=>`<i style="--h:${h}%"></i>`).join('')}</div>`}
function preview(){const b=variant==='B',c=variant==='C';return `<div class="preview"><div class="preview-head"><b>${b?'Ваши рекомендации':c?'Студия «Смысл» / Мой кабинет':'Proofwall / Партнёрская программа'}</b><span class="dots">•••</span></div><div class="preview-body"><div class="tiny muted">${b?'Польза возвращается':'Этот месяц · демонстрационные данные'}</div><div class="stats" style="margin-top:15px"><div class="stat"><label>${b?'Бонусы':c?'Мои продажи':'Продажи партнёров'}</label><strong>${b?'600 ₽':c?'24 000 ₽':'48 000 ₽'}</strong></div><div class="stat"><label>${b?'Друзья':c?'Мои комиссии':'Комиссии'}</label><strong>${b?'2':c?'4 800 ₽':'9 600 ₽'}</strong></div><div class="stat"><label>${b?'Доступно':c?'Мои клиенты':'Партнёры'}</label><strong>${b?'300 ₽':c?'4':'12'}</strong></div></div>${graph()}${row(b?'Мария оплатила подписку':'Новый платёж · проект «Атлас»',b?'+300 ₽':'+1 200 ₽')}<div class="tiny muted">${b?'300 ₽ ждут окончания периода возврата':'Комиссия появится в реестре после проверки'}</div></div></div><div class="float-card"><span class="check">✓</span><div><strong style="font-size:13px">${b?'Рекомендация сработала':'У каждого начисления есть причина'}</strong><div class="tiny muted">${b?'Следите за бонусом прямо в Proofwall':'Оплата → комиссия → реестр → перевод'}</div></div></div>`}
function hero(){const f=FLOWS[variant];return `<div class="hero"><div class="hero-copy"><span class="eyebrow">${f.entry}</span><h1>${f.title.replaceAll('\n','<br>')}</h1><p class="lead">${f.lead}</p>${button(f.cta)}<span class="tiny muted">${variant==='A'?'Сначала попробуйте на примере Proofwall.':variant==='B'?'Рекомендовать необязательно. Пользуйтесь продуктом как прежде.':'Участие бесплатно. Доход зависит от реальных оплат.'}</span></div><div class="art">${preview()}</div></div><div class="benefits">${f.benefits.map(t=>`<span>${t}</span>`).join('')}</div>`}
function workspace(title,subtitle,body,role){return `<div class="workspace"><aside class="sidebar"><b>◉ &nbsp; Proofwall</b><span class="side-item ${step===1?'current':''}">01 &nbsp; Начало работы</span><span class="side-item ${step===2?'current':''}">02 &nbsp; Начисления</span><span class="side-item ${step===3?'current':''}">03 &nbsp; ${variant==='B'?'Бонусы':'Выплаты'}</span><span class="side-item ${step===4?'current':''}">04 &nbsp; ${variant==='A'?'Тариф':'Вид владельца ↗'}</span><span class="side-item ${step===5?'current':''}">05 &nbsp; Материалы</span><div class="tiny muted" style="margin:35px 9px 0">Прототип кабинета<br>Данные — пример<br>Сентябрь 2026</div></aside><div class="work"><div class="work-top"><div><span class="eyebrow">${role||(variant==='A'?'Владелец SaaS':variant==='B'?'Клиент Proofwall':'Внешний партнёр')}</span><h1>${title}</h1><p class="muted" style="margin:0;font-size:13px">${subtitle}</p></div><span class="chip">${step+1} из 6</span></div>${body}</div></div>`}
function terms(){return `${row('Вознаграждение',variant==='B'?'300 ₽ на подписку':'20% от каждой оплаты')}${row('Атрибуция','Промокод важнее ссылки')}${row('Окно ссылки','30 дней · гипотеза')}${row('Проверка возвратов','14 дней · гипотеза')}${row('Получение',variant==='B'?'После проверки → баланс':'Ручной перевод до 5-го')}<p class="tiny">Все ставки демонстрационные. Дату закрытия реестра и перенос удержаний согласуем до разработки.</p>`}
function onboarding(){if(variant==='A')return workspace('Соберём вашу программу','Один проект, одна ставка. Остальное можно уточнить позже.',`<div class="two-col">${panel('01 / Платежи и вознаграждение',`<label class="field">Проект<input value="Proofwall" readonly></label><label class="field">Комиссия с каждой оплаты, %<input id="rate" type="number" min="1" max="50" value="${state.A.rate}"></label><div class="row"><span>ЮKassa · тестовый сценарий</span><span class="chip">${state.A.connected?'Демо подключено':'Не подключено'}</span></div>${button(state.A.connected?'Настроить заново':'Подключить демо ЮKassa','connect','secondary')}<div class="actions">${button('Проверить начисление')}</div>`)}${panel('Что произойдёт после оплаты',`<ol class="timeline"><li>Клиент приходит по рекомендации<small>Ссылка или промокод партнёра</small></li><li>Платёж подтверждён<small>В реализации — проверка уведомления провайдера</small></li><li>Появляется комиссия<small>Сначала на проверке, затем в реестре</small></li></ol>${notice('В демо ключи не нужны. Настоящее подключение и существующий код ЮKassa будут проверяться на этапе разработки.')}`,'pale')}</div>`);
return workspace(variant==='B'?'Бонус за полезную рекомендацию':'Условия видны до вступления',variant==='B'?'Вы сами решаете, участвовать ли в программе.':'Программа Proofwall для авторов и агентств.',`<div class="two-col">${panel('Правила программы',terms())}${panel('Присоединиться',`<label class="field">${variant==='B'?'Ваш профиль':'Название партнёра'}<input value="${variant==='B'?'Анна · клиент Proofwall':'Студия «Смысл»'}" readonly></label><label style="display:flex;gap:10px;font-size:13px;margin:23px 0"><input id="consent" type="checkbox" ${state[variant].joined?'checked':''}> Я прочитал(а) условия и хочу участвовать</label>${button('Вступить и увидеть пример','join')}<p>Это демо согласия. Заявка не отправляется, реальные данные не собираются.</p>`,'pale')}</div>`)}
function aha(){if(variant==='A'){const a=state.A,c=6000*a.rate/100;return workspace('Проверьте путь денег','Нажмите на тестовый платёж — начисление появится в истории.',`<div class="two-col">${panel('Проверочное начисление',`<div class="tiny muted">Платёж 6 000 ₽ × ${a.rate}%</div><div class="metric">${a.paid?money(a.refund?0:c):'— ₽'}</div><span class="chip">${!a.paid?'Ждём тестовый платёж':a.refund?'Начисление отменено':'На проверке'}</span><div class="actions">${button(a.paid?'Повторить событие':'Сымитировать платёж','payment')}${a.paid?button(a.refund?'Восстановить пример':'Проверить возврат','refund','secondary'):''}</div>${a.paid?`<p>${a.refund?'Возврат 6 000 ₽ → комиссия 0 ₽.':'Повтор события не увеличивает сумму в демо.'}</p>`:''}`)}${panel('История одного события',`<ol class="timeline"><li>Источник: партнёр «Студия»<small>Ссылка studio · демо-атрибуция</small></li><li>${a.paid?'Оплата подтверждена':'Ожидается подтверждение оплаты'}<small>PAY-DEMO-001 · 6 000 ₽</small></li><li>${a.refund?'Возврат: комиссия отменена':a.paid?'Комиссия '+money(c):'Комиссия ещё не начислена'}<small>${a.paid?'До реального подключения это лишь модель поведения':'Начисляем после успешной оплаты'}</small></li></ol>`,'pale')}</div><div class="actions">${button('Посмотреть реестр выплат')}</div>`)}
return workspace(variant==='B'?'Ваша рекомендация принесла бонус':'Вот откуда берётся ваша комиссия',variant==='B'?'Друг оплатил Proofwall. Бонус появился в вашем кабинете.':'За каждой суммой — конкретный платёж и его состояние.',`<div class="two-col">${panel(variant==='B'?'Мария подключила Proofwall':'Проект «Атлас» оплатил подписку',`<span class="chip">На проверке · демо</span><div class="metric">${variant==='B'?'+300 ₽':'+1 200 ₽'}</div><p>${variant==='B'?'Бонус станет доступен после проверки возвратов. Его можно использовать для своей подписки.':'6 000 ₽ × 20% = 1 200 ₽. После проверки комиссия войдёт в реестр выплат.'}</p>${button(variant==='B'?'Перейти к моим бонусам':'Посмотреть будущую выплату')}`,'pale')}${panel('Путь рекомендации',`<ol class="timeline"><li>Переход по вашей ссылке<small>2 сентября · личная рекомендация</small></li><li>Регистрация в Proofwall<small>3 сентября · источник сохранён</small></li><li>Успешная оплата<small>8 сентября · начисление на проверке</small></li><li>Окончание проверки<small>22 сентября · если не было возврата</small></li></ol><p>Даты и события иллюстративные; информация о клиентах партнёру показывается только в согласованном объёме.</p>`)}</div>`)}
function ledger(){if(variant==='A'&&agentState.manualHandoff)return renderManualAgentRegistry();if(variant==='B')return workspace('Польза вернулась к вам','Бонусы на подписку Proofwall. Это не денежная выплата.',`<div class="two-col">${panel('Ваш баланс',`<div class="stats"><div class="stat"><label>Доступно</label><strong>${state.B.applied?'0':'300'} ₽</strong></div><div class="stat"><label>На проверке</label><strong>300 ₽</strong></div><div class="stat"><label>Использовано</label><strong>${state.B.applied?'300':'0'} ₽</strong></div></div>${row('Подписка в следующем месяце','1 500 ₽')}${row('С учётом бонуса',state.B.applied?'1 200 ₽':'1 500 ₽')}<div class="actions">${button(state.B.applied?'Бонус применён':'Применить доступные 300 ₽','apply')}</div><p>Никаких списаний: кнопка меняет только демонстрационный баланс.</p>`)}${panel('Понятные ограничения',`<p>Бонус доступен после проверки оплаты друга. Он уменьшает стоимость собственной подписки и не выводится на карту.</p>${notice('Условия возврата, лимиты, срок жизни бонусов и порядок оформления ещё предстоит утвердить.')}<p>Если нужны денежные вознаграждения — сравните вариант C.</p>`,'pale')}</div><div class="actions">${button('Посмотреть сторону владельца')}</div>`);
if(variant==='C')return workspace('Выплаты без неизвестности','До 5-го числа следующего месяца — за предыдущий.',`<div class="two-col">${panel('За август 2026',`<div class="tiny muted">Перевод по реестру · демо</div><div class="metric">4 800 ₽</div><span class="chip">${state.C.sent?'Отправлено 4 сентября':'В реестре · до 5 сентября'}</span>${row('Способ','Перевод вручную')}${row('Кто отправляет','Команда Proofwall')}<div class="actions">${button(state.C.sent?'Показать ожидание':'Показать отправленный перевод','partner-sent','secondary')}</div><p>Кнопка переключает пример статуса, а не отправляет деньги.</p>`,'pale')}${panel('Сентябрь ещё открыт',`${row('Начислено','2 400 ₽')}${row('На проверке','1 200 ₽')}${row('Уже проверено','1 200 ₽')}<p>Ориентир выплаты — до 5 октября. Поздние начисления, возвраты и переносы требуют правила закрытия месяца.</p>${notice('«Отправлено» означает действие владельца. Подтверждение зачисления — отдельный вопрос, не обещание прототипа.')}`)}</div><div class="actions">${button('Посмотреть сторону владельца')}</div>`);
return workspace('Август закрыт. Осталось отправить.','Ручной реестр — основной сценарий для старта программы.',`<div class="stats" style="margin-top:24px"><div class="stat"><label>К переводу за август</label><strong>${state.A.sent?'0 ₽':'9 600 ₽'}</strong></div><div class="stat"><label>Партнёров в реестре</label><strong>3</strong></div><div class="stat"><label>Срок выплаты</label><strong>до 5 сентября</strong></div></div><div class="scroll"><table class="table"><thead><tr><th>Партнёр</th><th>Период</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>${[['Студия «Смысл»','4 800 ₽'],['Анна К.','2 400 ₽'],['Медиа «Рост»','2 400 ₽']].map(r=>`<tr><td>${r[0]}</td><td>Август 2026</td><td>${r[1]}</td><td><span class="chip">${state.A.sent?'Отправлено':'Готово к переводу'}</span></td></tr>`).join('')}</tbody></table></div>${notice('Владелец выгружает таблицу, делает переводы отдельно и отмечает отправку. Автоматические выплаты в этом сценарии не требуются.')}<div class="actions">${button('Скачать реестр CSV','csv','secondary')}${button(state.A.sent?'Сбросить отметку в демо':'Отметить отправку в демо','sent','secondary')}${button('Оценить тариф')}</div>`)}
function pricing(){return workspace('Тариф оплачивает владелец','Для клиентов и партнёров участие в программе бесплатно.',`<div class="two-col">${panel('Круг / Старт',`<span class="eyebrow">Ценовая гипотеза для обсуждения</span><div class="price" style="margin:17px 0">1 990 ₽ <small>/ месяц</small></div>${row('Операционный масштаб','До 100 партнёров')}${row('Учёт оплат и возвратов','Включён')}${row('Реестр ручных выплат','Включён')}${row('Кабинет партнёра','Включён')}<div class="actions">${button('Примерить тариф · без оплаты','plan')}</div><p>Цена и коммерческие лимиты не утверждены. «До 100» — рабочее допущение владельца о ручном процессе.</p>`)}${panel('Почему оплата появляется здесь',`<h2>${FLOWS[variant].paywall}</h2><p>${variant==='A'?'Владелец уже увидел, как оплата превращается в комиссию, и проверил реестр.':variant==='B'?'Владелец оценивает пилот на своей базе клиентов: приглашения, оплаты друзей и стоимость бонусов. Клиент не попадает на этот экран в рабочем продукте.':'Владелец запускает пробный период программы. Партнёр не попадает на этот экран в рабочем продукте.'}</p>${notice('Здесь показан переход роли для исследования CJM. В реализации кабинеты и права будут разделены.')}<div class="actions">${button(variant==='A'?'К приглашениям':variant==='B'?'Вернуться в кабинет клиента':'Вернуться в кабинет партнёра')}</div>`,'pale')}</div>`,'Владелец программы · смена роли')}
function invite(){return workspace(variant==='A'?'Первые партнёры начинаются с приглашения':'Ссылка готова. Добавьте свой голос.',variant==='A'?'Отправьте приглашение знакомым авторам или первым клиентам.':'Готовый текст помогает начать. Личная рекомендация делает его вашим.',`<div class="two-col">${panel('Личная ссылка и условия',`${linkbox()}${row('Продукт','Proofwall')}${row('Награда',variant==='B'?'300 ₽ на подписку':(variant==='A'?state.A.rate:20)+'% с оплат · пример')}${row('Получение',variant==='B'?'После проверки оплаты':'По реестру до 5-го')}<p>Адрес .example демонстрационный и не открывает реальную программу.</p>`,'pale')}${panel('Текст рекомендации',`<p class="quote">${variant==='A'?'Мы открываем партнёрскую программу Proofwall — сервиса для сбора отзывов. Если он подходит вашей аудитории, посмотрите условия. Комиссия считается с оплат, история доступна в кабинете.':variant==='B'?'Я собрала отзывы клиентов в Proofwall и поставила виджет на сайт. Возможно, вам тоже пригодится. По моей ссылке я получу бонус на подписку после вашей оплаты.':'Я использую Proofwall для отзывов и социальных доказательств. Посмотрите, подходит ли он вашему проекту. Это партнёрская ссылка: я получаю комиссию с оплаченной подписки.'}</p>${button('Скопировать текст и ссылку','copy-text','secondary')}<p>Ничего не отправляется автоматически. Текст можно изменить после копирования.</p>`)}</div><div class="actions">${button('Сравнить и выбрать направление','compare')}${button('Пройти этот путь сначала','restart','secondary')}</div>`)}
function render(){const f=FLOWS[variant];document.title=`Круг · ${variant} — ${f.name}`;$('#crumb').innerHTML=`<strong>${variant} / ${f.name}</strong> <span class="muted">· ${variant==='D'?(step===5?'Партнёр и его агент':'Владелец и его агент'):step===4?'Владелец программы':variant==='A'?'Владелец SaaS':variant==='B'?'Клиент Proofwall':'Внешний партнёр'}</span>`;$$('[role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.variant===variant)));$('#scene').innerHTML=variant==='D'?renderAgent():[hero,onboarding,aha,ledger,pricing,invite][step]();$('#steps').innerHTML=f.steps.map((s,i)=>`<button class="step ${i===step?'active':''}" data-step="${i}" ${i===step?'aria-current="step"':''}><span>0${i+1} / ${['ENTRY','ONBOARD','AHA','RETURN','PAYWALL','INVITE'][i]}</span><b>${s}</b></button>`).join('');$('#progress').textContent=`/ 0${step+1} — 06`;$('#insight').innerHTML=`<div><span class="eyebrow">Задача человека</span><p>${f.goals[step]}</p></div><div><span class="eyebrow">Что мешает</span><p>${f.friction[step]}</p></div><div><span class="eyebrow">Проверяемый UI-паттерн</span><p>${f.patterns[step]}</p></div>`;$('#insight').hidden=!notes;}
function toast(t){$('#toast').textContent=t;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').textContent='',4500)}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Скопировано. Отправьте, когда будете готовы.')}catch{const i=document.createElement('textarea');i.value=text;document.body.append(i);i.select();const ok=document.execCommand('copy');i.remove();toast(ok?'Скопировано.':'Браузер не разрешил копирование. Выделите текст вручную.')}}
function saveSelection(value){selected={...value,chosen_at:new Date().toISOString(),status:'proposal_for_user_review',prd_created:false};try{localStorage.setItem('n3-cjm-selection-v1',JSON.stringify(selected));toast('Выбор сохранён в этом браузере.')}catch{toast('Хранилище недоступно. Скачайте файл выбора.')}selectionUI()}
function selectionUI(){const valid=['A','B','C','D','mix'].includes(selected?.variant);$('#selection').innerHTML=valid?`<div class="selected"><strong>${selected.variant==='mix'?'Сохранено сочетание':`Выбран вариант ${selected.variant}`}</strong><p class="tiny">Скачайте решение и передайте его для продолжения. Прототип не создаёт PRD и не отправляет выбор автоматически.</p><div class="actions">${button('Скачать мой выбор JSON','export','secondary')}${button('Сбросить выбор','clear','secondary')}</div></div>`:'';}
function compare(){const areas=['entry','aha','paywall'];$('#comparison').innerHTML=Object.entries(FLOWS).map(([k,f])=>`<article class="compare-card"><span class="eyebrow">Вариант ${k}</span><h2>${f.name}</h2><p><b>Кто:</b> ${f.role}</p><p><b>Вход:</b> ${f.entry}</p><p><b>Aha:</b> ${f.aha}</p><p><b>Оплата:</b> ${f.paywall}</p><label class="field">Ваша оценка<select aria-label="Оценка варианта ${k}" data-score="${k}"><option value="">Не оценён</option>${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="primary" data-choose="${k}">Выбрать ${k}</button></article>`).join('');areas.forEach(a=>$('#mix-'+a).innerHTML=Object.entries(FLOWS).map(([k,f])=>`<option value="${k}">${k} · ${f[a]}</option>`).join(''));selectionUI();$('#compare').showModal()}
function advance(){if(variant==='A'&&step===1){const rate=Number($('#rate').value);if(!Number.isFinite(rate)||rate<1||rate>50){toast('Укажите комиссию от 1 до 50%.');return}state.A.rate=rate;if(!state.A.connected){toast('Сначала подключите демо ЮKassa.');return}}if((variant==='B'||variant==='C')&&step===1&&!state[variant].joined){toast('Для вступления нужно явное согласие.');return}if(step===2&&variant==='A'&&!state.A.paid){toast('Сначала проверьте тестовый платёж.');return}step=Math.min(5,step+1);render();$('#scene').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action?.startsWith('agent-')){handleAgent(b.dataset.action);return}if(b.dataset.variant){variant=b.dataset.variant;step=0;render();return}if(b.dataset.step!==undefined){step=Number(b.dataset.step);render();return}if(b.dataset.choose){saveSelection({variant:b.dataset.choose,scores:Object.fromEntries($$('[data-score]').map(s=>[s.dataset.score,s.value||null]))});return}switch(b.dataset.action){case'next':advance();break;case'connect':{const n=Number($('#rate').value);if(n<1||n>50||!Number.isFinite(n)){toast('Укажите комиссию от 1 до 50%.');break}state.A.rate=n;state.A.connected=true;render();toast('Демо подключено. Реальные ключи не использовались.');break}case'join':if(!$('#consent').checked){toast('Подтвердите добровольное участие.');break}state[variant].joined=true;advance();break;case'payment':if(!state.A.paid){state.A.paid=true;state.A.refund=false}else{toast('Повтор события: начисление не меняется.')}render();break;case'refund':state.A.refund=!state.A.refund;render();break;case'sent':state.A.sent=!state.A.sent;render();break;case'partner-sent':state.C.sent=!state.C.sent;render();break;case'apply':state.B.applied=true;render();toast('Демо: 300 ₽ учтены в следующей подписке.');break;case'plan':toast('Тариф отмечен для обсуждения. Оплата не запускалась.');break;case'csv':download('\uFEFFПартнёр;Период;Сумма_RUB;Срок;Статус\nСтудия Смысл;2026-08;4800;2026-09-05;'+(state.A.sent?'Отправлено':'К переводу')+'\nАнна К.;2026-08;2400;2026-09-05;'+(state.A.sent?'Отправлено':'К переводу')+'\nМедиа Рост;2026-08;2400;2026-09-05;'+(state.A.sent?'Отправлено':'К переводу'),'n3-demo-payouts-2026-08.csv','text/csv;charset=utf-8');break;case'copy':await copy($('#share-link').value);break;case'copy-text':await copy($('.quote').textContent+'\n'+$('#share-link').value);break;case'compare':compare();break;case'close':$('#compare').close();break;case'mix':saveSelection({variant:'mix',entry:$('#mix-entry').value,aha:$('#mix-aha').value,paywall:$('#mix-paywall').value});break;case'export':if(selected)download(JSON.stringify(selected,null,2),'n3-cjm-choice.json','application/json');break;case'clear':selected=null;try{localStorage.removeItem('n3-cjm-selection-v1')}catch{}selectionUI();break;case'restart':step=0;render();break;case'insight':notes=!notes;b.textContent=notes?'Скрыть CJM-заметки':'Показать CJM-заметки';b.setAttribute('aria-expanded',String(notes));$('#insight').hidden=!notes;break}});
render();
